<script setup lang="ts">import{ref,onMounted}from'vue';import{http}from'@/shared/api/httpClient';const items=ref<any[]>([]);const money=(v:number)=>v.toLocaleString('es-AR',{style:'currency',currency:'ARS'});onMounted(async()=>{items.value=(await http.get('/rentabilidad')).data});</script>
<template><section class="page"><div class="page-title"><div><h2>Rentabilidad</h2><p>Precio − costos operativos − IVA = ganancia neta.</p></div></div><div class="formula card"><span>Precio de venta</span><b>−</b><span>Compra + envío + otros</span><b>−</b><span>IVA aplicado</span><b>=</b><strong>Ganancia neta</strong></div><div class="panel"><table><thead><tr><th>Cliente</th><th>Venta</th><th>Costo operativo</th><th>IVA</th><th>Costo total</th><th>Ganancia bruta</th><th>Ganancia neta</th><th>Margen</th><th>Pendiente</th><th>Estado</th></tr></thead><tbody><tr v-for="r in items" :key="r.id"><td><b>{{r.cliente}}</b></td><td>{{money(r.precioTotal)}}</td><td>{{money(r.costoOperativo)}}</td><td>{{money(r.iva)}}</td><td>{{money(r.costoTotal)}}</td><td>{{money(r.gananciaBruta)}}</td><td><b :class="{negative:r.gananciaNeta<0}">{{money(r.gananciaNeta)}}</b></td><td>{{(r.margen*100).toFixed(2)}}%</td><td>{{money(r.totalPendiente)}}</td><td><span class="badge">{{r.estadoFinanciero}}</span></td></tr></tbody></table><div v-if="!items.length" class="empty">El reporte aparecerá al cargar ventas.</div></div></section></template>
